#### Saga Orchestrator (Azure Durable Functions)

```csharp
using Microsoft.Azure.WebJobs;
using Microsoft.Azure.WebJobs.Extensions.DurableTask;
using Microsoft.Extensions.Logging;

public class ClaimAdjudicationSaga
{
    private readonly IEligibilityService _eligibilityService;
    private readonly IBenefitsService _benefitsService;
    private readonly IPricingService _pricingService;
    private readonly IPaymentService _paymentService;
    private readonly ILogger<ClaimAdjudicationSaga> _logger;

    /// <summary>
    /// Saga orchestrator function coordinating claim adjudication workflow
    /// </summary>
    [FunctionName("ClaimAdjudicationSaga")]
    public async Task<ClaimAdjudicationResult> RunOrchestrator(
        [OrchestrationTrigger] IDurableOrchestrationContext context,
        ILogger log)
    {
        var claim = context.GetInput<Claim>();
        var sagaId = context.InstanceId;

        log.LogInformation($"Starting saga {sagaId} for claim {claim.ClaimId}");

        try
        {
            // Step 1: Verify Eligibility
            var eligibilityResult = await context.CallActivityAsync<EligibilityResult>(
                "VerifyEligibility",
                new EligibilityRequest
                {
                    MemberId = claim.MemberId,
                    ServiceDate = claim.ServiceDate,
                    SagaId = sagaId
                });

            if (!eligibilityResult.IsEligible)
            {
                log.LogWarning($"Saga {sagaId}: Eligibility check failed for member {claim.MemberId}");
                return ClaimAdjudicationResult.Denied(claim.ClaimId, "Member not eligible");
            }

            // Step 2: Validate Benefits
            var benefitsResult = await context.CallActivityAsync<BenefitsResult>(
                "ValidateBenefits",
                new BenefitsRequest
                {
                    MemberId = claim.MemberId,
                    ServiceCode = claim.ServiceCode,
                    SagaId = sagaId
                });

            if (!benefitsResult.IsCovered)
            {
                log.LogWarning($"Saga {sagaId}: Benefits validation failed for service {claim.ServiceCode}");

                // Compensate eligibility verification
                await context.CallActivityAsync(
                    "CompensateEligibility",
                    new CompensationRequest
                    {
                        MemberId = claim.MemberId,
                        SagaId = sagaId,
                        Reason = "Benefits not covered"
                    });

                return ClaimAdjudicationResult.Denied(claim.ClaimId, "Service not covered");
            }

            // Step 3: Calculate Pricing
            var pricingResult = await context.CallActivityAsync<PricingResult>(
                "CalculatePricing",
                new PricingRequest
                {
                    ClaimId = claim.ClaimId,
                    ProviderId = claim.ProviderId,
                    ServiceCode = claim.ServiceCode,
                    SagaId = sagaId
                });

            if (pricingResult.PaymentAmount <= 0)
            {
                log.LogWarning($"Saga {sagaId}: Pricing calculation failed with amount {pricingResult.PaymentAmount}");

                // Compensate in reverse order
                await context.CallActivityAsync(
                    "CompensateBenefits",
                    new CompensationRequest
                    {
                        MemberId = claim.MemberId,
                        SagaId = sagaId,
                        Reason = "Pricing calculation failed"
                    });

                await context.CallActivityAsync(
                    "CompensateEligibility",
                    new CompensationRequest
                    {
                        MemberId = claim.MemberId,
                        SagaId = sagaId,
                        Reason = "Pricing calculation failed"
                    });

                return ClaimAdjudicationResult.Denied(claim.ClaimId, "Pricing error");
            }

            // Step 4: Create Payment
            var paymentResult = await context.CallActivityAsync<PaymentResult>(
                "CreatePayment",
                new PaymentRequest
                {
                    ClaimId = claim.ClaimId,
                    ProviderId = claim.ProviderId,
                    Amount = pricingResult.PaymentAmount,
                    SagaId = sagaId
                });

            if (!paymentResult.Success)
            {
                log.LogError($"Saga {sagaId}: Payment creation failed for claim {claim.ClaimId}");

                // Full compensation cascade
                await context.CallActivityAsync(
                    "CompensatePricing",
                    new CompensationRequest
                    {
                        ClaimId = claim.ClaimId,
                        SagaId = sagaId,
                        Reason = "Payment creation failed"
                    });

                await context.CallActivityAsync(
                    "CompensateBenefits",
                    new CompensationRequest
                    {
                        MemberId = claim.MemberId,
                        SagaId = sagaId,
                        Reason = "Payment creation failed"
                    });

                await context.CallActivityAsync(
                    "CompensateEligibility",
                    new CompensationRequest
                    {
                        MemberId = claim.MemberId,
                        SagaId = sagaId,
                        Reason = "Payment creation failed"
                    });

                return ClaimAdjudicationResult.Denied(claim.ClaimId, "Payment processing error");
            }

            // Saga completed successfully
            log.LogInformation($"Saga {sagaId} completed successfully for claim {claim.ClaimId}. Payment: ${pricingResult.PaymentAmount}");

            return ClaimAdjudicationResult.Approved(
                claim.ClaimId,
                pricingResult.PaymentAmount,
                paymentResult.PaymentId);
        }
        catch (Exception ex)
        {
            log.LogError(ex, $"Saga {sagaId} failed with exception for claim {claim.ClaimId}");

            // Attempt full compensation on unexpected failure
            await CompensateAll(context, claim, sagaId);

            return ClaimAdjudicationResult.Error(claim.ClaimId, ex.Message);
        }
    }

    /// <summary>
    /// Compensate all saga steps in reverse order
    /// </summary>
    private async Task CompensateAll(
        IDurableOrchestrationContext context,
        Claim claim,
        string sagaId)
    {
        try
        {
            await context.CallActivityAsync(
                "CompensatePayment",
                new CompensationRequest { ClaimId = claim.ClaimId, SagaId = sagaId, Reason = "Saga failure" });
        }
        catch (Exception ex)
        {
            context.SetCustomStatus($"Payment compensation failed: {ex.Message}");
        }

        try
        {
            await context.CallActivityAsync(
                "CompensatePricing",
                new CompensationRequest { ClaimId = claim.ClaimId, SagaId = sagaId, Reason = "Saga failure" });
        }
        catch (Exception ex)
        {
            context.SetCustomStatus($"Pricing compensation failed: {ex.Message}");
        }

        try
        {
            await context.CallActivityAsync(
                "CompensateBenefits",
                new CompensationRequest { MemberId = claim.MemberId, SagaId = sagaId, Reason = "Saga failure" });
        }
        catch (Exception ex)
        {
            context.SetCustomStatus($"Benefits compensation failed: {ex.Message}");
        }

        try
        {
            await context.CallActivityAsync(
                "CompensateEligibility",
                new CompensationRequest { MemberId = claim.MemberId, SagaId = sagaId, Reason = "Saga failure" });
        }
        catch (Exception ex)
        {
            context.SetCustomStatus($"Eligibility compensation failed: {ex.Message}");
        }
    }

    /// <summary>
    /// Activity function: Verify member eligibility
    /// </summary>
    [FunctionName("VerifyEligibility")]
    public async Task<EligibilityResult> VerifyEligibility(
        [ActivityTrigger] EligibilityRequest request,
        ILogger log)
    {
        log.LogInformation($"Saga {request.SagaId}: Verifying eligibility for member {request.MemberId}");

        try
        {
            var result = await _eligibilityService.CheckEligibilityAsync(
                request.MemberId,
                request.ServiceDate);

            // Record saga participation for compensation
            await _eligibilityService.RecordSagaParticipation(
                request.SagaId,
                request.MemberId,
                result);

            return result;
        }
        catch (Exception ex)
        {
            log.LogError(ex, $"Saga {request.SagaId}: Eligibility verification failed");
            return EligibilityResult.Failure("Service unavailable");
        }
    }

    /// <summary>
    /// Activity function: Compensate eligibility verification
    /// </summary>
    [FunctionName("CompensateEligibility")]
    public async Task CompensateEligibility(
        [ActivityTrigger] CompensationRequest request,
        ILogger log)
    {
        log.LogWarning($"Saga {request.SagaId}: Compensating eligibility for member {request.MemberId}. Reason: {request.Reason}");

        try
        {
            await _eligibilityService.CompensateEligibilityCheck(
                request.SagaId,
                request.MemberId,
                request.Reason);

            log.LogInformation($"Saga {request.SagaId}: Eligibility compensation completed");
        }
        catch (Exception ex)
        {
            log.LogError(ex, $"Saga {request.SagaId}: Eligibility compensation failed");
            // Mark for manual review
            await _eligibilityService.MarkForManualReview(request.SagaId, ex.Message);
            throw;
        }
    }
}
```

