#### Event-Driven Saga (Member Plan Change)

```csharp
using Azure.Messaging.ServiceBus;
using Microsoft.Extensions.Logging;

/// <summary>
/// Member Service - Initiates plan change saga
/// </summary>
public class MemberService
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly IMemberRepository _memberRepository;
    private readonly ILogger<MemberService> _logger;

    public async Task<PlanChangeResult> RequestPlanChangeAsync(
        Guid memberId,
        string newPlanId,
        DateTime effectiveDate)
    {
        var sagaId = Guid.NewGuid().ToString();

        _logger.LogInformation($"Saga {sagaId}: Member {memberId} requesting plan change to {newPlanId}");

        // Update member record with pending plan change
        await _memberRepository.UpdatePlanStatus(
            memberId,
            newPlanId,
            PlanStatus.PendingChange,
            sagaId);

        // Publish PlanChangeRequested event
        var planChangeEvent = new PlanChangeRequestedEvent
        {
            SagaId = sagaId,
            MemberId = memberId,
            NewPlanId = newPlanId,
            EffectiveDate = effectiveDate,
            Timestamp = DateTime.UtcNow
        };

        await PublishEvent("plan-change-topic", planChangeEvent);

        _logger.LogInformation($"Saga {sagaId}: PlanChangeRequested event published");

        return PlanChangeResult.Initiated(sagaId, memberId);
    }

    /// <summary>
    /// Event handler: Plan change completed successfully
    /// </summary>
    public async Task OnPlanChangeCompleted(PlanChangeCompletedEvent evt)
    {
        _logger.LogInformation($"Saga {evt.SagaId}: Plan change completed for member {evt.MemberId}");

        // Update member status to active
        await _memberRepository.UpdatePlanStatus(
            evt.MemberId,
            evt.NewPlanId,
            PlanStatus.Active,
            evt.SagaId);

        _logger.LogInformation($"Saga {evt.SagaId}: Member plan status updated to Active");
    }

    /// <summary>
    /// Event handler: Plan change failed - compensate
    /// </summary>
    public async Task OnPlanChangeFailed(PlanChangeFailedEvent evt)
    {
        _logger.LogWarning($"Saga {evt.SagaId}: Plan change failed for member {evt.MemberId}. Reason: {evt.Reason}");

        // Revert member plan to original
        await _memberRepository.RevertPlanChange(
            evt.MemberId,
            evt.SagaId);

        // Publish compensation complete event
        var compensatedEvent = new MemberPlanCompensatedEvent
        {
            SagaId = evt.SagaId,
            MemberId = evt.MemberId,
            Reason = evt.Reason,
            Timestamp = DateTime.UtcNow
        };

        await PublishEvent("plan-change-compensation-topic", compensatedEvent);

        _logger.LogInformation($"Saga {evt.SagaId}: Member plan compensation completed");
    }
}

/// <summary>
/// Plan Service - Assigns plan to member
/// </summary>
public class PlanService
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly IPlanRepository _planRepository;
    private readonly ILogger<PlanService> _logger;

    /// <summary>
    /// Event handler: PlanChangeRequested event received
    /// </summary>
    public async Task OnPlanChangeRequested(PlanChangeRequestedEvent evt)
    {
        _logger.LogInformation($"Saga {evt.SagaId}: Assigning plan {evt.NewPlanId} to member {evt.MemberId}");

        try
        {
            // Validate plan exists and member eligible
            var plan = await _planRepository.GetPlanAsync(evt.NewPlanId);
            if (plan == null)
            {
                throw new PlanNotFoundException(evt.NewPlanId);
            }

            // Assign plan to member
            await _planRepository.AssignPlanToMember(
                evt.MemberId,
                evt.NewPlanId,
                evt.EffectiveDate,
                evt.SagaId);

            // Publish PlanAssigned event
            var planAssignedEvent = new PlanAssignedEvent
            {
                SagaId = evt.SagaId,
                MemberId = evt.MemberId,
                PlanId = evt.NewPlanId,
                EffectiveDate = evt.EffectiveDate,
                Timestamp = DateTime.UtcNow
            };

            await PublishEvent("plan-change-topic", planAssignedEvent);

            _logger.LogInformation($"Saga {evt.SagaId}: Plan assigned successfully");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Saga {evt.SagaId}: Plan assignment failed");

            // Publish failure event to trigger compensation
            var failedEvent = new PlanChangeFailedEvent
            {
                SagaId = evt.SagaId,
                MemberId = evt.MemberId,
                Reason = $"Plan assignment failed: {ex.Message}",
                FailedStep = "PlanAssignment",
                Timestamp = DateTime.UtcNow
            };

            await PublishEvent("plan-change-topic", failedEvent);
        }
    }

    /// <summary>
    /// Event handler: Compensate plan assignment
    /// </summary>
    public async Task OnPlanChangeCompensationRequested(MemberPlanCompensatedEvent evt)
    {
        _logger.LogWarning($"Saga {evt.SagaId}: Compensating plan assignment for member {evt.MemberId}");

        try
        {
            // Remove plan assignment
            await _planRepository.RemovePlanAssignment(
                evt.MemberId,
                evt.SagaId);

            _logger.LogInformation($"Saga {evt.SagaId}: Plan assignment compensation completed");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Saga {evt.SagaId}: Plan compensation failed");
            // Mark for manual review
            await _planRepository.MarkForManualReview(evt.SagaId, ex.Message);
        }
    }
}
```

