### Saga State Management

```csharp
/// <summary>
/// Saga state tracking for monitoring and recovery
/// </summary>
public class SagaStateManager
{
    private readonly ISagaStateRepository _stateRepository;
    private readonly ILogger<SagaStateManager> _logger;

    /// <summary>
    /// Initialize new saga execution
    /// </summary>
    public async Task<SagaState> InitializeSagaAsync(
        string sagaType,
        string sagaId,
        object sagaData)
    {
        var state = new SagaState
        {
            SagaId = sagaId,
            SagaType = sagaType,
            Status = SagaStatus.Started,
            CurrentStep = 0,
            TotalSteps = GetTotalSteps(sagaType),
            SagaData = JsonSerializer.Serialize(sagaData),
            StartedAt = DateTime.UtcNow,
            UpdatedAt = DateTime.UtcNow
        };

        await _stateRepository.InsertAsync(state);

        _logger.LogInformation($"Saga {sagaId}: Initialized with {state.TotalSteps} steps");

        return state;
    }

    /// <summary>
    /// Update saga progress after each step
    /// </summary>
    public async Task UpdateSagaProgressAsync(
        string sagaId,
        int stepNumber,
        string stepName,
        SagaStepStatus stepStatus)
    {
        var state = await _stateRepository.GetBySagaIdAsync(sagaId);

        state.CurrentStep = stepNumber;
        state.UpdatedAt = DateTime.UtcNow;

        // Add step execution record
        state.ExecutionHistory.Add(new SagaStepExecution
        {
            StepNumber = stepNumber,
            StepName = stepName,
            Status = stepStatus,
            ExecutedAt = DateTime.UtcNow
        });

        // Update overall saga status
        if (stepStatus == SagaStepStatus.Failed)
        {
            state.Status = SagaStatus.Compensating;
        }
        else if (stepNumber == state.TotalSteps && stepStatus == SagaStepStatus.Completed)
        {
            state.Status = SagaStatus.Completed;
            state.CompletedAt = DateTime.UtcNow;
        }

        await _stateRepository.UpdateAsync(state);

        _logger.LogInformation($"Saga {sagaId}: Step {stepNumber}/{state.TotalSteps} ({stepName}) - {stepStatus}");
    }

    /// <summary>
    /// Mark saga as failed with compensation complete
    /// </summary>
    public async Task MarkSagaFailedAsync(
        string sagaId,
        string failureReason,
        List<string> compensatedSteps)
    {
        var state = await _stateRepository.GetBySagaIdAsync(sagaId);

        state.Status = SagaStatus.Failed;
        state.FailureReason = failureReason;
        state.CompensatedSteps = compensatedSteps;
        state.CompletedAt = DateTime.UtcNow;
        state.UpdatedAt = DateTime.UtcNow;

        await _stateRepository.UpdateAsync(state);

        _logger.LogWarning($"Saga {sagaId}: Failed after compensating {compensatedSteps.Count} steps. Reason: {failureReason}");
    }
}
```

