#### Step 2: Create Saga Orchestrator

```csharp
using Microsoft.Azure.WebJobs;
using Microsoft.Azure.WebJobs.Extensions.DurableTask;

public class ProviderEnrollmentSaga
{
    [FunctionName("ProviderEnrollmentOrchestrator")]
    public async Task<EnrollmentResult> RunOrchestrator(
        [OrchestrationTrigger] IDurableOrchestrationContext context)
    {
        var request = context.GetInput<ProviderEnrollmentRequest>();
        var sagaId = context.InstanceId;

        var compensations = new List<string>();

        try
        {
            // Step 1: Create provider record
            var providerResult = await context.CallActivityAsync<ProviderResult>(
                "CreateProvider", request);

            if (!providerResult.Success)
                return EnrollmentResult.Failed("Provider creation failed");

            compensations.Add("DeleteProvider");

            // Step 2: Verify credentials (may take 5-15 minutes)
            var credentialResult = await context.CallActivityAsync<CredentialResult>(
                "VerifyCredentials", new CredentialRequest
                {
                    ProviderId = providerResult.ProviderId,
                    LicenseNumber = request.LicenseNumber
                });

            if (!credentialResult.IsVerified)
            {
                await Compensate(context, compensations);
                return EnrollmentResult.Failed("Credential verification failed");
            }

            compensations.Add("RemoveCredentials");

            // Step 3: Assign to networks
            var networkResult = await context.CallActivityAsync<NetworkResult>(
                "AssignNetwork", new NetworkRequest
                {
                    ProviderId = providerResult.ProviderId,
                    NetworkIds = request.NetworkIds
                });

            if (!networkResult.Success)
            {
                await Compensate(context, compensations);
                return EnrollmentResult.Failed("Network assignment failed");
            }

            compensations.Add("RemoveFromNetwork");

            // Step 4: Create contracts
            var contractResult = await context.CallActivityAsync<ContractResult>(
                "CreateContract", new ContractRequest
                {
                    ProviderId = providerResult.ProviderId,
                    FeeScheduleId = request.FeeScheduleId
                });

            if (!contractResult.Success)
            {
                await Compensate(context, compensations);
                return EnrollmentResult.Failed("Contract creation failed");
            }

            // Saga completed successfully
            return EnrollmentResult.Success(providerResult.ProviderId);
        }
        catch (Exception ex)
        {
            await Compensate(context, compensations);
            return EnrollmentResult.Error(ex.Message);
        }
    }

    private async Task Compensate(
        IDurableOrchestrationContext context,
        List<string> compensations)
    {
        // Execute compensations in reverse order
        for (int i = compensations.Count - 1; i >= 0; i--)
        {
            try
            {
                await context.CallActivityAsync(compensations[i], context.InstanceId);
            }
            catch (Exception ex)
            {
                // Log compensation failure for manual review
                context.SetCustomStatus($"Compensation failed: {compensations[i]} - {ex.Message}");
            }
        }
    }
}
```

