[FunctionName("CreateProvider")]
public async Task<ProviderResult> CreateProvider(
    [ActivityTrigger] ProviderEnrollmentRequest request,
    ILogger log)
{
    log.LogInformation($"Creating provider for license {request.LicenseNumber}");

    var provider = new Provider
    {
        LicenseNumber = request.LicenseNumber,
        Name = request.ProviderName,
        Specialty = request.Specialty,
        Status = ProviderStatus.Pending
    };

    await _providerRepository.CreateAsync(provider);

    return ProviderResult.Success(provider.ProviderId);
}

[FunctionName("DeleteProvider")]
public async Task DeleteProvider(
    [ActivityTrigger] string sagaId,
    ILogger log)
{
    log.LogWarning($"Saga {sagaId}: Compensating - deleting provider");

    var provider = await _providerRepository.GetBySagaIdAsync(sagaId);
    if (provider != null)
    {
        await _providerRepository.DeleteAsync(provider.ProviderId);
    }
}
