public class PlanServiceEventHandler : IHostedService
{
    private ServiceBusProcessor _processor;

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        var options = new ServiceBusProcessorOptions
        {
            MaxConcurrentCalls = 10,
            AutoCompleteMessages = false
        };

        _processor = _client.CreateProcessor("plan-change-topic", "plan-service-subscription", options);
        _processor.ProcessMessageAsync += ProcessMessageAsync;
        _processor.ProcessErrorAsync += ProcessErrorAsync;

        await _processor.StartProcessingAsync(cancellationToken);
    }

    private async Task ProcessMessageAsync(ProcessMessageEventArgs args)
    {
        var eventType = args.Message.ApplicationProperties["EventType"].ToString();
        var eventData = args.Message.Body.ToString();

        switch (eventType)
        {
            case "PlanChangeRequested":
                var evt = JsonSerializer.Deserialize<PlanChangeRequestedEvent>(eventData);
                await _planService.OnPlanChangeRequested(evt);
                break;

            case "PlanChangeCompensationRequested":
                var compEvt = JsonSerializer.Deserialize<CompensationRequestedEvent>(eventData);
                await _planService.OnCompensationRequested(compEvt);
                break;
        }

        await args.CompleteMessageAsync(args.Message);
    }
}
