**Best Practices for Compensating Transactions**:

1. **Make Operations Semantically Reversible**
```csharp
// Forward transaction
public async Task AssignPlanToMember(Guid memberId, string planId)
{
    var assignment = new PlanAssignment
    {
        MemberId = memberId,
        PlanId = planId,
        AssignedAt = DateTime.UtcNow,
        Status = PlanAssignmentStatus.Active
    };

    await _repository.CreateAsync(assignment);
}

// Compensating transaction
public async Task RevertPlanAssignment(Guid memberId, string sagaId)
{
    var assignment = await _repository.GetByMemberAndSagaAsync(memberId, sagaId);

    if (assignment != null)
    {
        assignment.Status = PlanAssignmentStatus.Reverted;
        assignment.RevertedAt = DateTime.UtcNow;
        assignment.RevertReason = "Saga compensation";

        await _repository.UpdateAsync(assignment);
        // Don't delete - keep for audit trail
    }
}
```

2. **Handle Compensation Failures**
```csharp
public async Task CompensateWithRetry(string compensationAction, int maxRetries = 3)
{
    for (int attempt = 1; attempt <= maxRetries; attempt++)
    {
        try
        {
            await ExecuteCompensation(compensationAction);
            return; // Success
        }
        catch (Exception ex)
        {
            if (attempt == maxRetries)
            {
                // Mark for manual review
                await _manualReviewQueue.EnqueueAsync(new ManualReviewTask
                {
                    SagaId = _sagaId,
                    CompensationAction = compensationAction,
                    FailureReason = ex.Message,
                    RequiresManualIntervention = true
                });

                throw;
            }

            await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt)));
        }
    }
}
