#### Implementation

**Saga Flow** (Happy Path):

```text
1. Claim submitted via API Gateway
2. Saga Orchestrator receives claim
3. Step 1: Eligibility Service verifies member coverage → Success
4. Step 2: Benefits Service validates service code coverage → Success
5. Step 3: Pricing Service calculates reimbursement amount → Success
6. Step 4: Prior Auth Service checks authorization requirements → Success (no auth required)
7. Step 5: TPL Service checks third-party liability → Success (no TPL)
8. Step 6: Payment Service creates provider payment → Success
9. Step 7: Audit Service logs claim decision → Success
10. Saga completes → Claim status: APPROVED, Payment: $150.00
```

**Saga Flow** (Failure with Compensation):

```text
1. Claim submitted via API Gateway
2. Saga Orchestrator receives claim
3. Step 1: Eligibility Service verifies member coverage → Success
4. Step 2: Benefits Service validates service code coverage → Success
5. Step 3: Pricing Service calculates reimbursement → FAILURE (provider not in fee schedule)
6. COMPENSATION BEGINS
7. Compensate Step 2: Benefits Service releases benefit authorization → Success
8. Compensate Step 1: Eligibility Service releases eligibility lock → Success
9. Saga fails → Claim status: DENIED, Reason: "Provider not in fee schedule"
```

**Code Implementation**:

```csharp
[FunctionName("ClaimAdjudicationSaga")]
public async Task<ClaimResult> RunOrchestrator(
    [OrchestrationTrigger] IDurableOrchestrationContext context)
{
    var claim = context.GetInput<Claim>();
    var sagaId = context.InstanceId;

    // Initialize saga state
    await context.CallActivityAsync(
        "InitializeSagaState",
        new SagaInitRequest { SagaId = sagaId, SagaType = "ClaimAdjudication", TotalSteps = 7 });

    try
    {
        // Step 1: Eligibility
        var eligResult = await context.CallActivityAsync<EligibilityResult>(
            "VerifyEligibility",
            new { MemberId = claim.MemberId, ServiceDate = claim.ServiceDate, SagaId = sagaId });

        if (!eligResult.IsEligible)
        {
            await context.CallActivityAsync(
                "UpdateSagaState",
                new { SagaId = sagaId, Step = 1, Status = "Failed", Reason = "Member not eligible" });
            return ClaimResult.Denied(claim.ClaimId, "Member not eligible");
        }

        await context.CallActivityAsync(
            "UpdateSagaState",
            new { SagaId = sagaId, Step = 1, Status = "Completed" });

        // Step 2: Benefits
        var benResult = await context.CallActivityAsync<BenefitsResult>(
            "ValidateBenefits",
            new { MemberId = claim.MemberId, ServiceCode = claim.ServiceCode, SagaId = sagaId });

        if (!benResult.IsCovered)
        {
            // Compensate eligibility
            await context.CallActivityAsync(
                "CompensateEligibility",
                new { MemberId = claim.MemberId, SagaId = sagaId, Reason = "Benefits validation failed" });

            await context.CallActivityAsync(
                "UpdateSagaState",
                new { SagaId = sagaId, Status = "Failed", CompensatedSteps = new[] { "Eligibility" } });

            return ClaimResult.Denied(claim.ClaimId, "Service not covered");
        }

        await context.CallActivityAsync(
            "UpdateSagaState",
            new { SagaId = sagaId, Step = 2, Status = "Completed" });

        // Step 3: Pricing (FAILS in this example)
        var priceResult = await context.CallActivityAsync<PricingResult>(
            "CalculatePricing",
            new { ClaimId = claim.ClaimId, ProviderId = claim.ProviderId, ServiceCode = claim.ServiceCode, SagaId = sagaId });

        if (priceResult.PaymentAmount <= 0)
        {
            // Compensate in reverse order
            await context.CallActivityAsync(
                "CompensateBenefits",
                new { MemberId = claim.MemberId, SagaId = sagaId, Reason = "Pricing calculation failed" });

            await context.CallActivityAsync(
                "CompensateEligibility",
                new { MemberId = claim.MemberId, SagaId = sagaId, Reason = "Pricing calculation failed" });

            await context.CallActivityAsync(
                "UpdateSagaState",
                new { SagaId = sagaId, Status = "Failed", CompensatedSteps = new[] { "Benefits", "Eligibility" } });

            return ClaimResult.Denied(claim.ClaimId, "Provider not in fee schedule");
        }

        // Continue with remaining steps...
        // (Steps 4-7 omitted for brevity)

        await context.CallActivityAsync(
            "UpdateSagaState",
            new { SagaId = sagaId, Status = "Completed" });

        return ClaimResult.Approved(claim.ClaimId, priceResult.PaymentAmount);
    }
    catch (Exception ex)
    {
        // Handle unexpected failure
        await CompensateAll(context, sagaId);

        await context.CallActivityAsync(
            "UpdateSagaState",
            new { SagaId = sagaId, Status = "Failed", Reason = ex.Message });

        return ClaimResult.Error(claim.ClaimId, ex.Message);
    }
}
