#### Implementation

**Event Flow** (Happy Path):

```text
1. Provider submits enrollment application via Gainwell Provider+™ portal
2. Provider Service creates provider record → publishes ProviderCreated event
3. Credentialing Service listens → starts license verification (5-15 min) → publishes CredentialsVerified event
4. Network Service listens → assigns provider to networks → publishes NetworkAssigned event
5. Contract Service listens → creates reimbursement contracts → publishes ContractCreated event
6. Directory Service listens → publishes provider to directory → publishes DirectoryPublished event
7. Notification Service listens → sends welcome email to provider → publishes NotificationSent event
8. Provider Service listens → updates status to ACTIVE
```

**Event Flow** (Failure with Compensation):

```text
1. Provider submits enrollment application
2. Provider Service creates provider record → publishes ProviderCreated event
3. Credentialing Service verifies license → publishes CredentialsVerified event
4. Network Service assigns to networks → publishes NetworkAssigned event
5. Contract Service starts contract creation → FAILS (state contract system timeout)
6. Contract Service publishes ContractCreationFailed event
7. COMPENSATION CASCADE:
   a. Network Service listens → removes network assignments → publishes NetworkCompensated event
   b. Credentialing Service listens → removes credentials → publishes CredentialsCompensated event
   c. Provider Service listens → marks provider enrollment FAILED → publishes ProviderEnrollmentFailed event
   d. Notification Service listens → sends failure email to provider
```

**Code Implementation**:

```csharp
// Provider Service - Initiates saga
public class ProviderService
{
    public async Task<EnrollmentResult> EnrollProviderAsync(ProviderApplication application)
    {
        var sagaId = Guid.NewGuid().ToString();

        // Create provider record
        var provider = new Provider
        {
            ProviderId = Guid.NewGuid(),
            LicenseNumber = application.LicenseNumber,
            Name = application.ProviderName,
            Status = ProviderStatus.Pending,
            SagaId = sagaId
        };

        await _providerRepository.CreateAsync(provider);

        // Publish event to trigger next step
        var providerCreatedEvent = new ProviderCreatedEvent
        {
            SagaId = sagaId,
            ProviderId = provider.ProviderId,
            LicenseNumber = provider.LicenseNumber,
            Specialty = application.Specialty,
            Timestamp = DateTime.UtcNow
        };

        await _eventPublisher.PublishAsync("provider-enrollment", providerCreatedEvent);

        _logger.LogInformation($"Saga {sagaId}: Provider enrollment initiated for {provider.ProviderId}");

        return EnrollmentResult.Initiated(sagaId, provider.ProviderId);
    }

    // Event handler: Enrollment completed successfully
    public async Task OnEnrollmentCompleted(DirectoryPublishedEvent evt)
    {
        var provider = await _providerRepository.GetBySagaIdAsync(evt.SagaId);

        if (provider != null)
        {
            provider.Status = ProviderStatus.Active;
            await _providerRepository.UpdateAsync(provider);

            _logger.LogInformation($"Saga {evt.SagaId}: Provider {provider.ProviderId} enrollment completed");
        }
    }

    // Event handler: Enrollment failed - compensate
    public async Task OnCredentialsCompensated(CredentialsCompensatedEvent evt)
    {
        var provider = await _providerRepository.GetBySagaIdAsync(evt.SagaId);

        if (provider != null)
        {
            provider.Status = ProviderStatus.EnrollmentFailed;
            provider.FailureReason = evt.Reason;
            await _providerRepository.UpdateAsync(provider);

            // Publish final compensation event
            var failedEvent = new ProviderEnrollmentFailedEvent
            {
                SagaId = evt.SagaId,
                ProviderId = provider.ProviderId,
                Reason = evt.Reason,
                Timestamp = DateTime.UtcNow
            };

            await _eventPublisher.PublishAsync("provider-enrollment", failedEvent);

            _logger.LogWarning($"Saga {evt.SagaId}: Provider {provider.ProviderId} enrollment failed and compensated");
        }
    }
}

// Contract Service - Saga participant that may fail
public class ContractService
{
    public async Task OnNetworkAssigned(NetworkAssignedEvent evt)
    {
        _logger.LogInformation($"Saga {evt.SagaId}: Creating contract for provider {evt.ProviderId}");

        try
        {
            // Attempt contract creation (may timeout calling state system)
            var contract = await _stateContractSystem.CreateContractAsync(
                evt.ProviderId,
                evt.NetworkIds,
                timeout: TimeSpan.FromSeconds(30));

            // Success - publish event
            var contractCreatedEvent = new ContractCreatedEvent
            {
                SagaId = evt.SagaId,
                ProviderId = evt.ProviderId,
                ContractId = contract.ContractId,
                Timestamp = DateTime.UtcNow
            };

            await _eventPublisher.PublishAsync("provider-enrollment", contractCreatedEvent);

            _logger.LogInformation($"Saga {evt.SagaId}: Contract {contract.ContractId} created successfully");
        }
        catch (TimeoutException ex)
        {
            _logger.LogError(ex, $"Saga {evt.SagaId}: Contract creation timed out");

            // Publish failure event to trigger compensation cascade
            var failedEvent = new ContractCreationFailedEvent
            {
                SagaId = evt.SagaId,
                ProviderId = evt.ProviderId,
                Reason = "State contract system timeout",
                Timestamp = DateTime.UtcNow
            };

            await _eventPublisher.PublishAsync("provider-enrollment", failedEvent);
        }
    }
}
